+  if (Object.prototype.hasOwnProperty.call(DEFAULT_CONDITIONS, name)) {
+    return DEFAULT_CONDITIONS[name as keyof typeof DEFAULT_CONDITIONS];
+  }
+
+  throw new ShortcutConditionError(`Unknown condition "${name}".`);
+}
