1. import { createContext, useContext, useEffect, useMemo, useState } from "react";
2. 
3. import actionsJson from "@/config/keyboardShortcuts.json";
4. import { useIsMobile } from "@/hooks/use-mobile";
5. import { useKeyboardShortcuts } from "@/hooks/useKeyboardShortcuts";
6. import { FacilityAction, FacilityActionId } from "@/types/shortcuts";
7. import {
8.   formatKeyboardShortcut,
9.   shortcutActionHandler,
10. } from "@/Utils/keyboardShortcutUtils";
11. import { expandShortcutContext } from "@/Utils/shortcutUtils";
12. 
13. interface ShortcutContextType {
14.   /**
15.    * Whether the command dialog is open
16.    */
17.   commandDialogOpen: boolean;
18.   /**
19.    * Set the command dialog open state
20.    */
21.   setCommandDialogOpen: (open: boolean) => void;
22.   /**
23.    * Current shortcut sub-context (e.g., "appointment-detail", "patient-detail")
24.    */
25.   subContext?: string;
26.   /**
27.    * Set the current shortcut sub-context
28.    */
29.   setSubContext: (subContext?: string) => void;
30.   /**
31.    * Whether shortcuts should run even when input fields are focused
32.    */
33.   ignoreInputFields: boolean;
34.   /**
35.    * Set whether shortcuts should run even when input fields are focused
36.    */
37.   setIgnoreInputFields: (ignore: boolean) => void;
38.   /**
39.    * Get the display string for a shortcut action ID based on current context
40.    */
41.   getShortcutDisplay: (actionId: string) => string | undefined;
42. }
43. 
44. const ShortcutContext = createContext<ShortcutContextType | null>(null);
45. 
46. interface ShortcutProviderProps {
47.   children: React.ReactNode;
48.   /**
49.    * Whether shortcuts should run even when input fields are focused
50.    * @default false
51.    */
52.   ignoreInputFields?: boolean;
53. }
54. 
55. export function ShortcutProvider({
56.   children,
57.   ignoreInputFields: defaultIgnoreInputFields = false,
58. }: ShortcutProviderProps) {
59.   const [commandDialogOpen, setCommandDialogOpen] = useState(false);
60.   const [subContext, setSubContext] = useState<string | undefined>();
61.   const [ignoreInputFields, setIgnoreInputFields] = useState(
62.     defaultIgnoreInputFields,
63.   );
64.   const isMobile = useIsMobile();
65. 
66.   // Facility shortcuts logic (moved from useShortcutSubContext)
67.   const actions = useMemo((): FacilityAction[] => {
68.     const allContexts = expandShortcutContext(subContext || "");
69. 
70.     return [
71.       ...(subContext?.includes("-global") ? [] : ["global"]),
72.       ...allContexts,
73.     ]
74.       .map((context) => {
75.         const contextActions = actionsJson[context as keyof typeof actionsJson];
76. 
77.         if (!contextActions) return [];
78.         return contextActions.map((a) => ({
79.           id: a.action,
80.           handler: shortcutActionHandler(a.action),
81.         }));
82.       })
83.       .flat();
84.   }, [subContext]);
85. 
86.   const handlers = useMemo(() => {
87.     const handlersMap = {} as Record<FacilityActionId, () => void>;
88. 
89.     actions.forEach((action) => {
90.       handlersMap[action.id] = () => {
91.         action.handler();
92.       };
93.     });
94. 
95.     return handlersMap;
96.   }, [actions]);
97. 
98.   // Function to get shortcut display string for an action ID
99.   const getShortcutDisplay = useMemo(() => {
100.     return (actionId: string): string | undefined => {
101.       if (isMobile) {
102.         return undefined;
103.       }
104. 
105.       // Search through current context hierarchy + global
106.       const allContexts = expandShortcutContext(subContext || "");
107.       const contextsToSearch = ["global", ...allContexts];
108. 
109.       for (const context of contextsToSearch) {
110.         const contextActions = actionsJson[context as keyof typeof actionsJson];
111.         if (!contextActions) continue;
112. 
113.         const shortcut = contextActions.find((s) => s.action === actionId);
114.         if (shortcut) {
115.           return formatKeyboardShortcut(shortcut.key);
116.         }
117.       }
118. 
119.       return undefined;
120.     };
121.   }, [subContext, isMobile]);
122. 
123.   // Set up facility shortcuts
124.   useKeyboardShortcuts(
125.     ["global", ...expandShortcutContext(subContext || "")],
126.     { canCreate: true },
127.     handlers,
128.     subContext,
129.     ignoreInputFields,
130.   );
131. 
132.   const value = useMemo(
133.     () => ({
134.       commandDialogOpen,
135.       setCommandDialogOpen,
136.       subContext,
137.       setSubContext,
138.       ignoreInputFields,
139.       setIgnoreInputFields,
140.       getShortcutDisplay,
141.     }),
142.     [commandDialogOpen, subContext, ignoreInputFields, getShortcutDisplay],
143.   );
144. 
145.   return (
146.     <ShortcutContext.Provider value={value}>
147.       {children}
148.     </ShortcutContext.Provider>
149.   );
150. }
151. 
152. export function useShortcuts() {
153.   const context = useContext(ShortcutContext);
154.   if (!context) {
155.     throw new Error("useShortcuts must be used within a ShortcutProvider");
156.   }
157.   return context;
158. }
159. 
160. /**
161.  * Hook to get shortcut display strings based on current context.
162.  * Returns a function that can be called with an action ID to get the display string.
163.  *
164.  * This hook automatically uses the current shortcut context hierarchy, so shortcuts
165.  * from parent contexts (e.g., "facility" when in "facility:patient:home") are available.
166.  * It also supports multiple context hierarchies with the & separator.
167.  *
168.  * @returns Function to get display string for an action ID
169.  *
170.  * @example
171.  * // In a component with context "facility:patient:home"
172.  * const getShortcutDisplay = useShortcutDisplay();
173.  * const printShortcut = getShortcutDisplay("print-button"); // "P" (from global or facility context)
174.  * const tokenShortcut = getShortcutDisplay("print-token"); // "P" (from facility:patient:home context)
175.  *
176.  * @example
177.  * // Usage in a button component
178.  * function PrintButton() {
179.  *   const getShortcutDisplay = useShortcutDisplay();
180.  *   const shortcut = getShortcutDisplay("print-button");
181.  *
182.  *   return (
183.  *     <button data-shortcut-id="print-button">
184.  *       Print {shortcut && <span className="ml-2 text-xs">({shortcut})</span>}
185.  *     </button>
186.  *   );
187.  * }
188.  */
189. export function useShortcutDisplay() {
190.   const { getShortcutDisplay } = useShortcuts();
191.   return getShortcutDisplay;
192. }
193. 
194. /**
195.  * Hook to set a shortcut sub-context for the current component.
196.  * This is a one-liner alternative to manually managing sub-contexts.
197.  *
198.  * @param subContext - The sub-context to set (e.g., "facility:appointment:detail")
199.  * @param options - Optional configuration
200.  * @param options.ignoreInputFields - Whether shortcuts should run even when input fields are focused
201.  *
202.  * @example
203.  * // Basic usage with just sub-context
204.  * useShortcutSubContext("patient:search:-global");
205.  *
206.  * @example
207.  * // With ignoreInputFields for dialogs/modals
208.  * const [open, setOpen] = useState(false);
209.  * useShortcutSubContext(
210.  *   open ? "patient:search:-global" : undefined,
211.  *   { ignoreInputFields: open }
212.  * );
213.  *
214.  * @example
215.  * // Always ignore input fields (e.g., for search pages)
216.  * useShortcutSubContext("patient:search:-global", { ignoreInputFields: true });
217.  */
218. export function useShortcutSubContext(
219.   subContext?: string,
220.   options?: {
221.     ignoreInputFields?: boolean;
